## 3. 分布式锁

### 3.1 Redis 分布式锁

```
Redis 分布式锁实现：

┌─────────────────────────────────────────────────────────────┐
│                    Redis 锁结构                              │
├─────────────────────────────────────────────────────────────┤
│                                                             │
│  SET key value NX PX milliseconds                          │
│  ├── NX: 不存在才设置                                       │
│  └── PX: 过期时间（毫秒）                                   │
│                                                             │
│  释放锁（Lua 脚本）：                                        │
│  ├── 检查 value 是否匹配                                    │
│  └── 删除 key                                               │
│                                                             │
└─────────────────────────────────────────────────────────────┘
```

### 3.2 Go 实现分布式锁

```go
// distributed_lock.go

package concurrency

import (
    "context"
    "crypto/rand"
    "encoding/hex"
    "time"
)

type DistributedLock struct {
    key      string
    value    string
    ttl      time.Duration
    redis    *RedisClient
}

func NewDistributedLock(key string, ttl time.Duration, redis *RedisClient) *DistributedLock {
    // 生成唯一值
    bytes := make([]byte, 16)
    rand.Read(bytes)
    value := hex.EncodeToString(bytes)

    return &DistributedLock{
        key:   key,
        value: value,
        ttl:   ttl,
        redis: redis,
    }
}

func (dl *DistributedLock) Acquire(ctx context.Context) bool {
    // SET key value NX PX ttl
    return dl.redis.SetNX(ctx, dl.key, dl.value, dl.ttl)
}

func (dl *DistributedLock) Release(ctx context.Context) bool {
    // Lua 脚本释放锁
    script := `
        if redis.call("get", KEYS[1]) == ARGV[1] then
            return redis.call("del", KEYS[1])
        else
            return 0
        end
    `
    return dl.redis.Eval(ctx, script, []string{dl.key}, dl.value)
}

// Redlock 算法（多Redis实例）
type Redlock struct {
    locks   []*DistributedLock
    quorum  int
    ttl     time.Duration
}

func NewRedlock(n int, ttl time.Duration) *Redlock {
    locks := make([]*DistributedLock, n)
    for i := 0; i < n; i++ {
        locks[i] = NewDistributedLock("lock", ttl, nil)
    }
    return &Redlock{
        locks:  locks,
        quorum: n/2 + 1,
        ttl:    ttl,
    }
}

func (rm *Redlock) Acquire(ctx context.Context) bool {
    acquired := 0
    startTime := time.Now()

    for _, lock := range rm.locks {
        if lock.Acquire(ctx) {
            acquired++
        }
    }

    // 计算实际锁持有时间
    elapsed := time.Since(startTime)
    validTTL := rm.ttl - elapsed

    if acquired >= rm.quorum {
        // 续期
        for _, lock := range rm.locks {
            if lock.IsHeld() {
                lock.Extend(ctx, validTTL)
            }
        }
        return true
    }

    // 释放已获取的锁
    for _, lock := range rm.locks {
        if lock.IsHeld() {
            lock.Release(ctx)
        }
    }
    return false
}
```

