## 第五部分：连接池

### 5.1 连接池原理

```
连接池解决的问题：
1. 频繁创建/销毁连接的开销
2. 连接泄漏（未关闭连接）
3. 连接数失控

连接池的关键参数：
1. MaxOpen：最大打开连接数
2. MaxIdle：最大空闲连接数
3. IdleTimeout：空闲超时时间
4. MaxLifetime：最大生命周期
```

### 5.2 Go 实现连接池

```go
package pool

import (
    "context"
    "fmt"
    "sync"
    "time"
)

// Connection 连接接口
type Connection interface {
    Close() error
    IsValid() bool
}

// Pool 连接池
type Pool struct {
    conns        chan Connection
    factory      func() (Connection, error)
    maxOpen      int
    maxIdle      int
    idleTimeout  time.Duration
    maxLifetime  time.Duration
    mu           sync.Mutex
    openCount    int
    closed       bool
}

// NewPool 创建连接池
func NewPool(factory func() (Connection, error), maxOpen, maxIdle int, idleTimeout, maxLifetime time.Duration) *Pool {
    p := &Pool{
        conns:       make(chan Connection, maxOpen),
        factory:     factory,
        maxOpen:     maxOpen,
        maxIdle:     maxIdle,
        idleTimeout: idleTimeout,
        maxLifetime: maxLifetime,
    }

    // 启动空闲连接清理
    go p.cleanup()

    return p
}

// Get 获取连接
func (p *Pool) Get(ctx context.Context) (Connection, error) {
    select {
    case conn := <-p.conns:
        if conn.IsValid() {
            return conn, nil
        }
        // 连接无效，创建新连接
    case <-ctx.Done():
        return nil, ctx.Err()
    }

    // 创建新连接
    p.mu.Lock()
    if p.openCount < p.maxOpen {
        p.openCount++
        p.mu.Unlock()
    } else {
        p.mu.Unlock()
        // 等待有空闲连接
        select {
        case conn := <-p.conns:
            if conn.IsValid() {
                return conn, nil
            }
        case <-ctx.Done():
            return nil, ctx.Err()
        }
    }

    // 创建新连接
    conn, err := p.factory()
    if err != nil {
        p.mu.Lock()
        p.openCount--
        p.mu.Unlock()
        return nil, err
    }

    return conn, nil
}

// Put 归还连接
func (p *Pool) Put(conn Connection) {
    if conn == nil || !conn.IsValid() {
        p.mu.Lock()
        p.openCount--
        p.mu.Unlock()
        return
    }

    select {
    case p.conns <- conn:
    default:
        // 池已满，关闭连接
        conn.Close()
        p.mu.Lock()
        p.openCount--
        p.mu.Unlock()
    }
}

// cleanup 清理空闲连接
func (p *Pool) cleanup() {
    ticker := time.NewTicker(30 * time.Second)
    defer ticker.Stop()

    for range ticker.C {
        p.mu.Lock()
        if p.closed {
            p.mu.Unlock()
            return
        }
        p.mu.Unlock()

        // 清理超时连接
        // ...
    }
}

// Close 关闭连接池
func (p *Pool) Close() error {
    p.mu.Lock()
    p.closed = true
    p.mu.Unlock()

    close(p.conns)
    return nil
}
