## 1. 多级缓存架构

### 1.1 缓存分层

```
多级缓存架构：

┌─────────────────────────────────────────────────────────────┐
│                    应用层缓存                                │
│  ├── L1: 本地缓存 (Caffeine/Guava)                         │
│  ├── L2: 分布式缓存 (Redis)                                 │
│  └── L3: 持久化存储 (DB)                                   │
└─────────────────────────────────────────────────────────────┘
```

### 1.2 Go 实现多级缓存

```go
// multi_level_cache.go

package cache

import (
    "sync"
    "time"
)

type MultiLevelCache struct {
    l1 *LocalCache
    l2 *DistributedCache
    db *Database
}

type LocalCache struct {
    items  map[string]*cacheEntry
    mu     sync.RWMutex
    maxLen int
}

type DistributedCache struct {
    redis *RedisClient
}

type cacheEntry struct {
    value     interface{}
    expireAt  time.Time
}

func NewMultiLevelCache() *MultiLevelCache {
    return &MultiLevelCache{
        l1: NewLocalCache(10000),
        l2: NewDistributedCache(),
        db: NewDatabase(),
    }
}

func (mc *MultiLevelCache) Get(key string) (interface{}, bool) {
    // L1 本地缓存
    if val, ok := mc.l1.Get(key); ok {
        return val, true
    }

    // L2 分布式缓存
    if val, ok := mc.l2.Get(key); ok {
        mc.l1.Set(key, val)
        return val, true
    }

    // L3 数据库
    val, ok := mc.db.Get(key)
    if ok {
        mc.l2.Set(key, val)
        mc.l1.Set(key, val)
        return val, true
    }

    return nil, false
}
```

