// cache_protection.go

package cache

import (
    "sync"
    "time"
)

// 布隆过滤器
type BloomFilter struct {
    bits []bool
    size int
}

func NewBloomFilter(size int) *BloomFilter {
    return &BloomFilter{
        bits: make([]bool, size),
        size: size,
    }
}

func (bf *BloomFilter) Add(key string) {
    // 简化实现
    idx := hash(key) % bf.size
    bf.bits[idx] = true
}

func (bf *BloomFilter) MightContain(key string) bool {
    idx := hash(key) % bf.size
    return bf.bits[idx]
}

// 热点 Key 保护
type HotKeyProtector struct {
    mutexes map[string]*sync.Mutex
    mu      sync.Mutex
}

func NewHotKeyProtector() *HotKeyProtector {
    return &HotKeyProtector{
        mutexes: make(map[string]*sync.Mutex),
    }
}

func (hkp *HotKeyProtector) GetOrCreate(key string, fetch func() (interface{}, error)) (interface{}, error) {
    hkp.mu.Lock()
    mutex, ok := hkp.mutexes[key]
    if !ok {
        mutex = &sync.Mutex{}
        hkp.mutexes[key] = mutex
    }
    hkp.mu.Unlock()

    mutex.Lock()
    defer mutex.Unlock()

    // 双重检查
